  function jsonSnapshot(model){const snapshot=C.clone(model);for(const page of snapshot.pages||[]){C.walkBlocks(page.blocks||[],b=>{if(b.asset)b.asset={name:b.asset.name||'',path:b.imagePath||b.asset.name||''};});}return snapshot;}
  function chapterFromFilename(name){const match=String(name||'').trim().match(/^(\d{2})(?=\s|[-_.]|$)/);if(!match)return null;const value=Number(match[1]);return value>=1&&value<=99?value:null;}
