    const selector=$('code-chapter-select');selector.innerHTML=chapters.map(ch=>'<option value="'+E(ch.id)+'">'+E(ch.label)+'</option>').join('')+'<option value="all">全部章节</option>';selector.value=doc.activeChapter;
    codeView=chapters.find(ch=>ch.id===doc.activeChapter)||{id:'all',start:0,end:doc.text.length};
