  async function loadLectureDefaults(){if(!state.lectureManifest)return;try{const styleText=await lectureFetch(state.lectureManifest.style);state.styles=[{name:'_hanhai.sty',text:styleText}];mergeLectureFigureDependencies(styleText);const assets={};for(const relative of state.lectureManifest.pictures||[]){try{const blob=await lectureFetch(relative,'blob');assets[relative.split('/').pop()]={name:relative.split('/').pop(),data:await dataURL(blob)};}catch{}}state.assets=assets;renderFiles();convertAll(false);}catch(e){status(e.message,true);}}
