  function renderLecturePPT(){const chosen=state.config.lectureSelection||[],selected=chosen.length?chosen:state.files.filter(file=>{const n=C.lectureChapter(file.name);return n!==null&&n<=9;}).map(file=>file.name);$('lecture-tex-select').innerHTML='<p class="muted">默认勾选 00–09；首次点击任意章节后仅保留该章，之后可继续多选。全部取消后恢复默认。</p>'+state.files.map(file=>'<label class="frame-choice"><input type="checkbox" data-lecture-ppt="'+E(file.name)+'"'+(selected.includes(file.name)?' checked':'')+'><span>'+E(file.name)+'</span></label>').join('');}
  function renderFiles(){const entries=[...state.files.map((f,i)=>({f,key:'tex:'+i})),...state.styles.map((f,i)=>({f,key:'sty:'+i}))];if(!entries.some(e=>e.key===state.active))state.active=entries[0]?.key||'tex:0';$('file-select').innerHTML=entries.map(e=>`<option value="${e.key}">${E(e.f.name)}</option>`).join('');$('file-select').value=state.active;$('file-count').textContent=`(${entries.length} + ${Object.keys(state.assets).length} 图片)`;$('file-list').innerHTML=entries.map(e=>`<p>${E(e.f.name)} <button data-remove-file="${e.key}">移除</button></p>`).join('')+Object.keys(state.assets).map(name=>`<p>图片 · ${E(name)}</p>`).join('');$('recent-files').innerHTML=state.recent.slice(0,6).map(f=>`<p class="muted">最近：${E(f.name)} · ${E(f.date)}</p>`).join('');}
  function get(path){return path.split('.').reduce((a,k)=>a?.[k],state.config);}
